 1	import java.util.ArrayList;
 2	import java.util.List;
 3	import java.util.Objects;
 4	
 5	public final class NaivePatternSearch {
 6	
 7	    private NaivePatternSearch() {
 8	    }
 9	
10	    public static List<Integer> search(String pattern, String text) {
11	        return search(new SearchRequest(text, pattern)).matchIndexes();
12	    }
13	
14	    public static SearchResult search(SearchRequest request) {
15	        Objects.requireNonNull(request, "request must not be null");
16	
17	        if (request.patternIsLongerThanText()) {
18	            return new SearchResult(request, List.of());
19	        }
20	
21	        List<Integer> matchIndexes = new ArrayList<>();
22	        int patternLength = request.patternLength();
23	
24	        for (int startIndex = 0;
25	                startIndex <= request.textLength() - patternLength;
26	                startIndex++) {
27	            if (matchesAt(request, startIndex, patternLength)) {
28	                matchIndexes.add(startIndex);
29	            }
30	        }
31	
32	        return new SearchResult(request, matchIndexes);
33	    }
34	
35	    public static String joinMatchIndexes(List<Integer> matches) {
36	        Objects.requireNonNull(matches, "matches must not be null");
37	
38	        if (matches.isEmpty()) {
39	            return "";
40	        }
41	
42	        StringBuilder formattedMatches = new StringBuilder();
43	        for (int index = 0; index < matches.size(); index++) {
44	            if (index > 0) {
45	                formattedMatches.append(' ');
46	            }
47	            formattedMatches.append(matches.get(index));
48	        }
49	
50	        return formattedMatches.toString();
51	    }
52	
53	    private static boolean matchesAt(SearchRequest request, int startIndex, int patternLength) {
54	        for (int offset = 0; offset < patternLength; offset++) {
55	            if (request.text().charAt(startIndex + offset)
56	                    != request.pattern().charAt(offset)) {
57	                return false;
58	            }
59	        }
60	
61	        return true;
62	    }
63	}

